import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../core/api_paths.dart';import '../../core/providers.dart';import '../../widgets/async_panel.dart';import '../../widgets/records_list.dart';
class CommunicationScreen extends ConsumerWidget{const CommunicationScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final api=ref.watch(apiClientProvider);return Scaffold(appBar:AppBar(title:const Text('Communication')),body:AsyncPanel(future:api.get(ApiPaths.communicationSummary),builder:(context,data){final d=Map<String,dynamic>.from(data as Map);return DefaultTabController(length:3,child:Column(children:[const TabBar(tabs:[Tab(text:'Tasks'),Tab(text:'Announcements'),Tab(text:'Notifications')]),Expanded(child:TabBarView(children:[RecordsList(rows:(d['tasks'] as List).map((e)=>Map<String,dynamic>.from(e as Map)).toList()),RecordsList(rows:(d['announcements'] as List).map((e)=>Map<String,dynamic>.from(e as Map)).toList()),RecordsList(rows:(d['notifications'] as List).map((e)=>Map<String,dynamic>.from(e as Map)).toList())]))]));}));}}
